### Problem
The task is to determine if a given text is a haiku. The definition of a haiku includes having exactly 17 syllables distributed in a 5-7-5 pattern.

### Previous Answer
import re

def is_haiku(text):
    lines = text.strip().split('\n')
    if len(lines) != 3:
        return False

    def count_syllables(line):
        count = 0
        vowels = 'aeiouy'
        prev_char = None

        for char in line.lower():
            if char == ' ':
                continue
            if char in vowels:
                if prev_char not in vowels and prev_char != ' ':
                    count += 1
                elif prev_char == 'e' and (line.find(prev_char) < line.rfind('e') or line.find(prev_char) + 2 >= len(line))):
                    count -= 1
            prev_char = char

        return count

    return all(count_syllables(line) == n for n, line in zip([5, 7, 5]], lines))))

